const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={step:1,students:[],subjects:[],photos:new Map(),errors:[],warnings:[],fileName:'',classes:JSON.parse(localStorage.getItem('karname_classes')||'[]')};
const faDigits='۰۱۲۳۴۵۶۷۸۹';
const fa=n=>String(n??'').replace(/\d/g,d=>faDigits[d]);
const en=s=>String(s??'').replace(/[۰-۹]/g,d=>faDigits.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));
const clean=s=>String(s??'').replace(/\u200c/g,' ').replace(/\s+/g,' ').trim();
const key=s=>clean(en(s)).replace(/[^\p{L}\p{N}]/gu,'').toLowerCase();
const scoreText=n=>n==null?'—':fa(Number(n).toLocaleString('fa-IR',{maximumFractionDigits:2}));
const toast=msg=>{const t=$('#toast');t.textContent=msg;t.className='toast-visible';clearTimeout(t._x);t._x=setTimeout(()=>t.className='',2700)};

function showView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===id));$('.sidebar').classList.remove('open');scrollTo({top:0,behavior:'smooth'})}
$$('[data-go]').forEach(b=>b.onclick=()=>showView(b.dataset.go));$$('.nav-item').forEach(b=>b.onclick=()=>showView(b.dataset.view));
$('#newReport').onclick=()=>showView('builder');$('#menuBtn').onclick=()=>$('.sidebar').classList.toggle('open');

function getSettings(){return {school:clean($('#schoolName').value),year:clean($('#schoolYear').value),grade:$('#grade').value,period:clean($('#period').value),classNo:clean($('#classNo').value),group:clean($('#groupName').value),manager:clean($('#managerName').value)}}
function setSettings(s={}){if(s.school)$('#schoolName').value=s.school;if(s.year)$('#schoolYear').value=s.year;if(s.grade)$('#grade').value=s.grade;if(s.period)$('#period').value=s.period;if(s.classNo)$('#classNo').value=s.classNo;if(s.group)$('#groupName').value=s.group;if(s.manager)$('#managerName').value=s.manager}
function saveClass(){const s=getSettings();if(!s.school)return;const sig=[s.school,s.year,s.grade,s.period,s.classNo].join('|');const old=state.classes.find(x=>x.sig===sig);const item={...s,sig,updated:Date.now()};if(old)Object.assign(old,item);else state.classes.unshift(item);state.classes=state.classes.slice(0,30);localStorage.setItem('karname_classes',JSON.stringify(state.classes));localStorage.setItem('karname_school',s.school);renderClasses();refreshHeader()}
function refreshHeader(){const name=localStorage.getItem('karname_school')||getSettings().school||'مدرسه شما';$('#schoolTitle').textContent=name;$('#schoolInitial').textContent=name[0]||'م';$('#classCount').textContent=fa(state.classes.length);if(state.classes[0])$('#lastActivity').textContent=new Intl.DateTimeFormat('fa-IR',{month:'long',day:'numeric'}).format(state.classes[0].updated)}
function renderClasses(){const box=$('#classList');if(!state.classes.length){box.innerHTML='<div class="empty-card"><b>هنوز کلاسی ساخته نشده است</b><span>با ساخت اولین گروه کارنامه، تنظیمات آن اینجا نمایش داده می‌شود.</span></div>';return}box.innerHTML=state.classes.map((c,i)=>`<article class="class-card"><div class="class-top"><span class="class-badge">${c.period}</span><button class="ghost danger remove-class" data-i="${i}">حذف</button></div><h3>${c.group||`${c.grade} · کلاس ${c.classNo}`}</h3><p>${c.school}</p><div class="class-meta"><div><small>سال تحصیلی</small><b>${c.year}</b></div><div><small>پایه و کلاس</small><b>${c.grade} · ${c.classNo}</b></div></div><button class="secondary small use-class" data-i="${i}" style="width:100%;margin-top:14px">ساخت کارنامه برای این کلاس</button></article>`).join('');$$('.use-class').forEach(b=>b.onclick=()=>{setSettings(state.classes[+b.dataset.i]);showView('builder');goStep(2)});$$('.remove-class').forEach(b=>b.onclick=()=>{state.classes.splice(+b.dataset.i,1);localStorage.setItem('karname_classes',JSON.stringify(state.classes));renderClasses();refreshHeader()})}

function goStep(n){state.step=Math.max(1,Math.min(4,n));$$('.step-panel').forEach(p=>p.classList.toggle('active',+p.dataset.panel===state.step));$$('.wizard-tabs button').forEach(t=>t.classList.toggle('active',+t.dataset.step===state.step));$('#prevStep').disabled=state.step===1;$('#nextStep').style.display=state.step===4?'none':'';$('#progressText').textContent=`مرحله ${fa(state.step)} از ۴`;$('#progressBar').style.width=`${state.step*25}%`;if(state.step===4)renderValidation()}
$$('.wizard-tabs button').forEach(t=>t.onclick=()=>goStep(+t.dataset.step));$('#prevStep').onclick=()=>goStep(state.step-1);$('#nextStep').onclick=()=>{if(state.step===1){const s=getSettings();if(!s.school||!s.year||!s.grade||!s.period||!s.classNo){toast('فیلدهای اصلی تنظیمات کلاس را کامل کنید.');return}saveClass()}goStep(state.step+1)};

const known={id:['کددانشآموزی','کددانشاموزی','کددانشآموز','studentid','code','کدملی'],first:['نام','firstname'],last:['نامخانوادگی','نامخانوادگي','lastname'],full:['نامونامخانوادگی','نامونامخانوادگي','نامکامل','fullname'],comment:['نظر','توضیحات','توضيحات','comment','یادداشت']};
function detectHeader(headers,type){return headers.findIndex(h=>known[type].includes(key(h)))}
function parseRows(rows,fileName){state.errors=[];state.warnings=[];state.students=[];state.subjects=[];state.fileName=fileName;const nonEmpty=rows.filter(r=>r.some(v=>clean(v)!==''));if(nonEmpty.length<2){state.errors.push('فایل باید حداقل یک ردیف عنوان و یک دانش‌آموز داشته باشد.');renderExcel();return}const headers=nonEmpty[0].map(clean);const idx={id:detectHeader(headers,'id'),first:detectHeader(headers,'first'),last:detectHeader(headers,'last'),full:detectHeader(headers,'full'),comment:detectHeader(headers,'comment')};if(idx.first<0&&idx.full<0)state.errors.push('ستون «نام» یا «نام و نام خانوادگی» پیدا نشد.');if(idx.last<0&&idx.full<0)state.errors.push('ستون «نام خانوادگی» پیدا نشد.');if(idx.id<0)state.warnings.push('ستون کد دانش‌آموزی پیدا نشد؛ برای تطبیق عکس‌ها بهتر است این ستون را اضافه کنید.');const reserved=new Set(Object.values(idx).filter(i=>i>=0));state.subjects=headers.map((name,i)=>({name:clean(name),i})).filter(x=>x.name&&!reserved.has(x.i));if(!state.subjects.length)state.errors.push('هیچ ستون درسی پیدا نشد.');if(state.subjects.length>32)state.errors.push(`تعداد درس‌ها ${fa(state.subjects.length)} است؛ حداکثر قابل نمایش ۳۲ درس است.`);const ids=new Set();for(let r=1;r<nonEmpty.length;r++){const row=nonEmpty[r];const first=idx.full>=0?clean(row[idx.full]):clean(row[idx.first]);const last=idx.full>=0?'':clean(row[idx.last]);if(!first&&!last)continue;let id=idx.id>=0?clean(row[idx.id]):`ROW-${r}`;if(ids.has(key(id)))state.errors.push(`کد تکراری «${fa(id)}» در ردیف ${fa(r+1)}.`);ids.add(key(id));const scores={};for(const sub of state.subjects){const raw=clean(row[sub.i]);if(raw===''){scores[sub.name]=null;continue}const normalized=en(raw).replace(',','.');const n=Number(normalized);if(!Number.isFinite(n)||n<0||n>20){state.errors.push(`نمره «${fa(raw)}» برای ${first} ${last} در درس ${sub.name} معتبر نیست.`);scores[sub.name]=null}else scores[sub.name]=n}state.students.push({id,first,last,comment:idx.comment>=0?clean(row[idx.comment]):'',scores})}if(!state.students.length)state.errors.push('هیچ دانش‌آموزی در فایل پیدا نشد.');renderExcel();renderPhotos();}

async function readExcel(file){if(!file)return;if(file.size>10*1024*1024){toast('حجم فایل بیشتر از ۱۰ مگابایت است.');return}try{if(!window.XLSX)throw Error('کتابخانه خواندن اکسل بارگذاری نشده است.');const data=await file.arrayBuffer();const wb=XLSX.read(data,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];const rows=XLSX.utils.sheet_to_json(ws,{header:1,raw:true,defval:''});parseRows(rows,file.name);toast('فایل اکسل بررسی شد.')}catch(e){state.errors=[`خواندن فایل ممکن نشد: ${e.message}`];renderExcel()}}
function renderExcel(){const el=$('#excelResult');if(!state.fileName&&!state.errors.length){el.innerHTML='';return}const valid=state.errors.length===0;el.innerHTML=`<div class="file-report"><div class="file-report-head"><div><b>${state.fileName||'فایل نامعتبر'}</b><small>${valid?' · آماده ادامه':' · نیازمند اصلاح'}</small></div><span class="class-badge">${valid?'تأیید شد':'خطا'}</span></div><div class="checks"><div class="check ${state.students.length?'ok':'bad'}"><b>${fa(state.students.length)}</b><small>دانش‌آموز شناسایی‌شده</small></div><div class="check ${state.subjects.length&&state.subjects.length<=32?'ok':'bad'}"><b>${fa(state.subjects.length)}</b><small>درس پویا</small></div><div class="check ${valid?'ok':'bad'}"><b>${fa(state.errors.length)}</b><small>خطای مسدودکننده</small></div></div>${state.errors.length?`<ul class="error-list">${state.errors.slice(0,12).map(x=>`<li>${x}</li>`).join('')}${state.errors.length>12?`<li>و ${fa(state.errors.length-12)} خطای دیگر…</li>`:''}</ul>`:''}${state.warnings.length?`<ul class="error-list" style="color:#a36d08">${state.warnings.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}</div>`}

function setupDrop(id,input,handler){const z=$(id),f=$(input);f.onchange=()=>handler(f.files[0]);['dragenter','dragover'].forEach(x=>z.addEventListener(x,e=>{e.preventDefault();z.classList.add('drag')}));['dragleave','drop'].forEach(x=>z.addEventListener(x,e=>{e.preventDefault();z.classList.remove('drag')}));z.addEventListener('drop',e=>{const file=e.dataTransfer.files[0];if(file)handler(file)})}
setupDrop('#excelDrop','#excelFile',readExcel);
setupDrop('#zipDrop','#zipFile',readZip);

async function readZip(file){if(!file)return;try{if(!window.JSZip)throw Error('کتابخانه ZIP بارگذاری نشده است.');for(const url of state.photos.values())URL.revokeObjectURL(url);state.photos.clear();const zip=await JSZip.loadAsync(await file.arrayBuffer());const entries=Object.values(zip.files).filter(x=>!x.dir&&/\.(jpe?g|png|webp)$/i.test(x.name));for(const entry of entries){const base=entry.name.split('/').pop().replace(/\.[^.]+$/,'');const blob=await entry.async('blob');state.photos.set(key(base),URL.createObjectURL(blob))}renderPhotos();toast(`${fa(entries.length)} تصویر از ZIP خوانده شد.`)}catch(e){toast(`خواندن ZIP ممکن نشد: ${e.message}`)}}
function renderPhotos(){const el=$('#photoResult');if(!state.photos.size){el.className='match-summary empty';el.innerHTML='<span>هنوز تصویری وارد نشده است؛ این مرحله اختیاری است.</span>';return}const matched=state.students.filter(s=>state.photos.has(key(s.id))).length;const missing=Math.max(0,state.students.length-matched);const extra=Math.max(0,state.photos.size-matched);el.className='match-summary';el.innerHTML=`<div class="match-grid"><div><b style="color:#078c77">${fa(matched)}</b><small>تصویر تطبیق‌یافته</small></div><div><b style="color:#b67a0a">${fa(missing)}</b><small>دانش‌آموز بدون تصویر</small></div><div><b>${fa(extra)}</b><small>تصویر بدون دانش‌آموز</small></div></div>`}

function checks(){const s=getSettings(),missingPhotos=state.students.filter(x=>!state.photos.has(key(x.id))).length;return [
{type:s.school&&s.year&&s.grade&&s.period&&s.classNo?'ok':'bad',title:'تنظیمات کلاس',text:s.school?'مشخصات عمومی تکمیل شده است.':'نام مدرسه یا مشخصات کلاس ناقص است.'},
{type:state.students.length?'ok':'bad',title:'فهرست دانش‌آموزان',text:state.students.length?`${fa(state.students.length)} دانش‌آموز برای تولید آماده است.`:'فایل اکسل معتبر وارد نشده است.'},
{type:state.subjects.length&&state.subjects.length<=32?'ok':'bad',title:'تعداد درس‌ها',text:state.subjects.length?`${fa(state.subjects.length)} درس به‌صورت خودکار شناسایی شد.`:'ستون‌های درسی شناسایی نشده‌اند.'},
{type:state.errors.length?'bad':'ok',title:'اعتبار نمره‌ها',text:state.errors.length?`${fa(state.errors.length)} خطا باید در فایل اصلاح شود.`:'همه نمره‌ها عددی و در بازه ۰ تا ۲۰ هستند.'},
{type:state.photos.size?(missingPhotos?'warn':'ok'):'warn',title:'تطبیق تصاویر',text:state.photos.size?`${fa(state.students.length-missingPhotos)} تصویر تطبیق یافته و ${fa(missingPhotos)} تصویر مفقود است.`:'تصویری وارد نشده؛ کارنامه با جای‌نگهدار ساخته می‌شود.'},
{type:'ok',title:'حریم خصوصی',text:'فایل‌ها فقط در حافظه مرورگر پردازش می‌شوند.'}]}
function renderValidation(){$('#validationSummary').innerHTML=`<div class="validation-grid">${checks().map(c=>`<div class="validation-item ${c.type}"><span>${c.type==='ok'?'✓':c.type==='warn'?'!':'×'}</span><div><b>${c.title}</b><small>${c.text}</small></div></div>`).join('')}</div>`}

function averages(){const avgs={};state.subjects.forEach(sub=>{const vals=state.students.map(s=>s.scores[sub.name]).filter(Number.isFinite);avgs[sub.name]=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0});return avgs}
function studentAverage(s){const v=Object.values(s.scores).filter(Number.isFinite);return v.length?v.reduce((a,b)=>a+b,0)/v.length:0}
function ranks(){return [...state.students].sort((a,b)=>studentAverage(b)-studentAverage(a)).reduce((m,s,i)=>(m.set(s.id,i+1),m),new Map())}
function splitSubjects(){const groups=[];for(let i=0;i<state.subjects.length;i+=16)groups.push(state.subjects.slice(i,i+16));return groups}
function subjectRow(student,subs){const boxes=[];for(let i=0;i<4;i++){const part=subs.slice(i*4,i*4+4);boxes.push(`<div class="subject-box"><table><thead><tr><th>نام درس</th><th>نمره</th></tr></thead><tbody>${[0,1,2,3].map(j=>part[j]?`<tr><td>${part[j].name}</td><td>${scoreText(student.scores[part[j].name])}</td></tr>`:'<tr><td>&nbsp;</td><td>—</td></tr>').join('')}</tbody></table></div>`)}return `<div class="subject-row">${boxes.join('')}</div>`}
function card(student,rank,classAvg){const s=getSettings(),photo=state.photos.get(key(student.id)),avg=studentAverage(student);return `<article class="report-card"><div class="report-title">کارنامه ${s.period} ${s.school}</div><div class="student-head">${photo?`<img class="student-photo" src="${photo}" alt="عکس ${student.first}">`:'<div class="student-photo photo-placeholder">◉</div>'}<div class="student-info"><div class="info-cell wide">نام: <b>${student.first} ${student.last}</b></div><div class="info-cell">پایه: <b>${s.grade}</b></div><div class="info-cell">کلاس: <b>${fa(s.classNo)}</b></div><div class="info-cell wide">سال تحصیلی: <b>${fa(s.year)}</b></div><div class="info-cell wide">کد دانش‌آموزی: <b>${fa(student.id.replace('ROW-',''))}</b></div><div class="info-cell comment">نظر: <b>${student.comment||'—'}</b></div></div></div><div class="subjects-wrap">${splitSubjects().map(x=>subjectRow(student,x)).join('')}</div><div class="rank-line"><div>رتبه در کلاس: <b>${fa(rank)}</b></div><div>معدل دانش‌آموز: <b>${scoreText(avg)}</b></div><div>میانگین معدل کلاس: <b>${scoreText(classAvg)}</b></div></div><div class="chart-wrap"><canvas data-id="${student.id}"></canvas></div></article>`}
function renderPreview(){const bad=checks().some(x=>x.type==='bad');if(bad){goStep(4);toast('پیش از تولید، خطاهای قرمز را اصلاح کنید.');return}saveClass();const avgMap=averages(),rankMap=ranks();const classAvg=state.students.reduce((a,s)=>a+studentAverage(s),0)/state.students.length;let html='';for(let i=0;i<state.students.length;i+=2)html+=`<section class="print-sheet">${card(state.students[i],rankMap.get(state.students[i].id),classAvg)}${state.students[i+1]?card(state.students[i+1],rankMap.get(state.students[i+1].id),classAvg):''}</section>`;$('#printArea').innerHTML=html;$('#previewMeta').textContent=`${fa(state.students.length)} کارنامه · ${fa(Math.ceil(state.students.length/2))} صفحه A4`;showView('preview');requestAnimationFrame(()=>$$('.chart-wrap canvas').forEach(c=>drawChart(c,state.students.find(s=>s.id===c.dataset.id),avgMap)))}
function drawChart(canvas,student,avgs){const rect=canvas.getBoundingClientRect(),dpr=Math.max(2,devicePixelRatio||1);canvas.width=Math.floor(rect.width*dpr);canvas.height=Math.floor(rect.height*dpr);const g=canvas.getContext('2d');g.scale(dpr,dpr);const w=rect.width,h=rect.height,p={l:25,r:8,t:7,b:23};g.clearRect(0,0,w,h);g.font='6px Vazirmatn';g.textAlign='center';g.strokeStyle='#e3e5eb';g.lineWidth=.7;for(let v=0;v<=20;v+=5){const y=p.t+(20-v)*(h-p.t-p.b)/20;g.beginPath();g.moveTo(p.l,y);g.lineTo(w-p.r,y);g.stroke();g.fillStyle='#7b8290';g.fillText(fa(v),12,y+2)}const count=state.subjects.length,step=(w-p.l-p.r)/Math.max(count,1),bar=Math.min(8,step*.34);const points=[];state.subjects.forEach((sub,i)=>{const x=p.l+step*(i+.5),val=student.scores[sub.name]??0,y=p.t+(20-val)*(h-p.t-p.b)/20;g.fillStyle='#7776df';g.fillRect(x-bar,y,bar*2,h-p.b-y);const ay=p.t+(20-avgs[sub.name])*(h-p.t-p.b)/20;points.push([x,ay]);g.save();g.translate(x+2,h-2);g.rotate(-Math.PI/4);g.fillStyle='#555d6c';g.textAlign='right';g.fillText(sub.name.slice(0,12),0,0);g.restore()});g.strokeStyle='#f14bb3';g.lineWidth=1.4;g.beginPath();points.forEach((pnt,i)=>i?g.lineTo(...pnt):g.moveTo(...pnt));g.stroke();g.fillStyle='#f14bb3';points.forEach(pnt=>{g.beginPath();g.arc(...pnt,1.7,0,Math.PI*2);g.fill()})}

function loadDemo(){const subjects=['قرآن','معارف اسلامی','املای فارسی','زبان عربی','زبان انگلیسی','علوم تجربی','ریاضیات','ورزش','مطالعات اجتماعی','فرهنگ و هنر','کار و فناوری','تفکر','فارسی','نگارش','انضباط','آمادگی دفاعی','رایانه','پژوهش'];const names=[['ستیلا','ابراهیمی'],['هلیا','استادکریم'],['یسنا','افرازه'],['سحر','اکبری'],['درسا','اکبری'],['ستایش','بالال'],['النا','بالای‌گلی'],['آیدا','بایندر']];state.subjects=subjects.map((name,i)=>({name,i:i+4}));state.students=names.map((n,i)=>{const scores={};subjects.forEach((s,j)=>scores[s]=Math.min(20,Math.round((13+((i*7+j*3)%8)+((i+j)%3)*.25)*100)/100));return{id:`140510${String(i+1).padStart(2,'0')}`,first:n[0],last:n[1],comment:i===0?'تلاش و پیشرفت شما قابل تقدیر است.':'با آرزوی موفقیت بیشتر',scores}});state.fileName='داده نمونه داخلی';state.errors=[];state.warnings=[];setSettings({school:'دبیرستان دوره اول فرهنگ',year:'۱۴۰۶–۱۴۰۵',grade:'هفتم',period:'آبان ماه',classNo:'۷۰۲',group:'هفتم ۲'});renderExcel();renderPhotos();toast('داده نمونه با ۱۸ درس بارگذاری شد.')}
$('#loadDemo').onclick=()=>{loadDemo();showView('builder');goStep(4)};$('#demoFromReview').onclick=()=>{loadDemo();renderValidation()};$('#previewBtn').onclick=renderPreview;$('#printBtn').onclick=()=>window.print();$('#zoomToggle').onclick=()=>$('#printArea').classList.toggle('zoomed');
$('#downloadTemplate').onclick=()=>{if(!window.XLSX){toast('کتابخانه اکسل هنوز بارگذاری نشده است.');return}const data=[['کد دانش‌آموزی','نام','نام خانوادگی','نظر','قرآن','ریاضی','علوم'],['۱۴۰۵۱۰۰۱','نمونه','دانش‌آموز','تلاش خوب',18.5,19,17.75]];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(data),'نمرات');XLSX.writeFile(wb,'قالب-نمرات-کارنامه.xlsx')};
$('#resetApp').onclick=()=>{if(confirm('تنظیمات مدرسه و کلاس‌های ذخیره‌شده در این مرورگر پاک شود؟')){localStorage.removeItem('karname_classes');localStorage.removeItem('karname_school');state.classes=[];renderClasses();refreshHeader();toast('تنظیمات محلی پاک شد.')}};
window.addEventListener('beforeunload',()=>{for(const url of state.photos.values())URL.revokeObjectURL(url)});
renderClasses();refreshHeader();goStep(1);
